{
  "characters": [
    {
      "id": "C01",
      "name": "小宁",
      "role": "protagonist",
      "description": "高三学生，热爱画画，因摔伤住院错过高考。性格清醒、有原则，最终选择放弃假成绩，用自己的作品申请艺术方向课程。",
      "goals": [
        "学画画",
        "查清假成绩的真相",
        "用自己的真实能力申请艺术方向课程"
      ]
    },
    {
      "id": "C02",
      "name": "父亲",
      "role": "supporting",
      "description": "小宁的父亲，认定只有名校才有出路。因女儿错过高考而焦虑，一度接受中介的假成绩安排，最终承认错误并支持女儿走真实的路。",
      "goals": [
        "让女儿上名校",
        "弥补女儿错过高考的遗憾",
        "最终支持女儿的真实选择"
      ]
    },
    {
      "id": "C03",
      "name": "中介",
      "role": "antagonist",
      "description": "升学中介，声称可以安排高考成绩，实际是让替考者冒名参加考试。不断催促父亲交钱，并暗示一旦被追问孩子前途就完了。",
      "goals": [
        "骗取父亲的钱财",
        "促成假成绩升学交易"
      ]
    },
    {
      "id": "C04",
      "name": "小岚",
      "role": "supporting",
      "description": "小宁的朋友，帮同学整理过本班考试材料，保留了一份考场座位表。她提供关键线索，帮助小宁比对证据。",
      "goals": [
        "帮助小宁查清真相"
      ]
    }
  ],
  "scenes": [
    {
      "id": "S01",
      "title": "她没去的考试",
      "summary": "小宁想学画画但父亲认定只有名校才有出路；高考前小宁摔伤住院错过考试，中介私下向父亲承诺可以安排成绩。",
      "text": "高三学生小宁想学画画，父亲却认定只有名校才有出路。高考前小宁摔伤住院，错过考试。一个升学中介私下对父亲说：“人不用到，成绩我们安排。”父亲以为有特殊补考名额，交了钱。小宁问到底怎么考，中介没有回答。",
      "character_ids": ["C01", "C02", "C03"],
      "event_ids": ["E01", "E02", "E03"]
    },
    {
      "id": "S02",
      "title": "一份不属于她的成绩",
      "summary": "中介发来写有小宁名字的高考成绩单和模糊的入场核验照片，催父亲办升学材料；小宁质疑自己当时在医院，父亲劝她先别问，她把材料存进手机。",
      "text": "中介发来一份写着小宁名字的高考成绩单，还有一张模糊的入场核验照片，催父亲赶紧办升学材料。小宁说：“可那两天我一直在医院。”父亲反复看着高分，劝她先别问，错过就没有机会了。她把成绩单和照片都存进手机。",
      "character_ids": ["C01", "C02", "C03"],
      "event_ids": ["E04", "E05"]
    },
    {
      "id": "S03",
      "title": "朋友留下的线索",
      "summary": "小岚来还毕业纪念册，留下考场座位表，指出照片中模糊的座位号不是小宁的位置；小宁约她带原始材料核对，纪念册里夹着小宁的自画像。",
      "text": "小岚来还毕业纪念册，她帮同学整理过本班的考试材料，留下了一份考场座位表。她指着照片里一处模糊的座位号说：“我记得这个位置坐的不是你。”小宁没有立刻下结论，约她把原始材料带来核对。纪念册里夹着小宁画了很久的自画像。",
      "character_ids": ["C01", "C04"],
      "event_ids": ["E06", "E07"]
    },
    {
      "id": "S04",
      "title": "再交一笔钱",
      "summary": "中介以核验为由让父亲再交协调费，并暗示一旦有人追问孩子前途就完了；父亲准备借钱，小宁按住他手机要求先查清楚成绩是谁的。",
      "text": "中介说升学材料需要进一步核验，让父亲再交一笔“协调费”。他暗示一旦有人追问，孩子的前途就完了。父亲又准备借钱，小宁按住他的手机：“先查清楚，那份成绩到底是谁的。”",
      "character_ids": ["C01", "C02", "C03"],
      "event_ids": ["E08", "E09"]
    },
    {
      "id": "S05",
      "title": "她决定拆穿",
      "summary": "小岚带来原始座位表，两人比对中介的入场照片和小宁的住院记录，确认是替考；小宁对父亲说“你给我买的未来，连里面的人都不是我”。",
      "text": "小岚带来原始座位表，两人比对中介的入场照片和小宁的住院记录。照片里的考生坐在另一名同学的座位，考试当天小宁仍躺在病床上。父女这才确认：所谓特殊名额是让另一个人替她参加高考。小宁把证据存好，对父亲说：“你给我买的未来，连里面的人都不是我。”",
      "character_ids": ["C01", "C02", "C04"],
      "event_ids": ["E10", "E11"]
    },
    {
      "id": "S06",
      "title": "放弃那条捷径",
      "summary": "父亲承认自己不敢面对女儿错过考试，只想抓住名校名额；父女保存证据，主动向学校说明情况，停止使用假成绩，父亲把画册推回女儿面前。",
      "text": "父亲承认自己不敢面对女儿错过考试，只想抓住一个名校名额。父女保存中介承诺、付款记录和原始材料，主动向相关学校说明情况，停止使用假成绩，愿意配合核查。父亲把借款页面关掉，把画册推回女儿面前：“那我们从你真正会的事情开始。”",
      "character_ids": ["C01", "C02"],
      "event_ids": ["E12", "E13", "E14"]
    },
    {
      "id": "S07",
      "title": "她自己的名字",
      "summary": "过了一段时间，小宁用自己的画申请艺术方向课程，拿到作品面试邀请，把邀请和自画像放在父亲面前；父亲第一次认真翻完她的毕业纪念册。",
      "text": "过了一段时间，小宁用自己的画申请艺术方向课程，拿到了作品面试邀请。她把邀请和那张自画像放在父亲面前：“这一次，上面的名字和作品，都是我的。”父亲第一次认真翻完她的毕业纪念册。",
      "character_ids": ["C01", "C02"],
      "event_ids": ["E15", "E16"]
    }
  ],
